import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="HIPERPOTASEMIA"; N=7
SRC="Ortiz A, et al. Documento de consenso sobre el abordaje de la hiperpotasemia. Nefrología 2023;43(5):765-82"
P=[
page(1,N,T,big("HIPERPOTASEMIA",134,nowrap=True)+big(f'EL CALCIO <span style="color:{R}">NO</span> BAJA EL POTASIO',116)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Protege, desplaza y elimina: el orden del tratamiento, con ficha final para guardar.</div>',cover=True),
page(2,N,T,big("¿CUÁNTO ES GRAVE?",124,nowrap=True)+f'<div style="display:flex;flex-direction:column;gap:22px">{row("Leve","5,0–5,9 mEq/L")}{row("Moderada","6,0–6,4 mEq/L")}<div style="border-top:4px solid {K};padding-top:22px;display:flex;justify-content:space-between;gap:32px;font-size:40px;color:{R}"><div style="font-weight:800">Grave</div><div style="font-weight:800;text-align:right">≥ 6,5 mEq/L</div></div></div>'+f'<div style="border-top:4px solid {K};padding-top:28px;font-size:42px;font-weight:800;line-height:1.3">O con repercusión en el ECG</div>'),
page(3,N,T,kicker("PASO 1 · PROTEGE")+big("CALCIO IV",200,R,True)+f'<div style="display:flex;flex-direction:column;gap:22px">{row("Gluconato cálcico","1.000 mg (10 ml al 10 %)")}{row("Ritmo","En 2–3 min, monitorizado")}{row("Efecto","En minutos; dura 30–60 min")}</div>'+f'<div style="font-size:36px;line-height:1.4;color:{G}">Si la emergencia persiste, se puede repetir cada 30–60 min si no ha subido la calcemia.</div>'),
page(4,N,T,kicker("PASO 2 · DESPLAZA")+big("INSULINA + GLUCOSA",110,R,True)+f'<div style="display:flex;flex-direction:column;gap:22px">{row("Insulina rápida","10 UI")}{row("En","500 ml de glucosado al 10 %")}{row("Ritmo","En 1 hora")}</div>'+f'<div style="font-size:36px;line-height:1.4;color:{G}">Es la medida más eficaz: empieza en 10–20 min y dura hasta 6 h. Insulina sola si la glucemia es &gt; 250 mg/dl.</div>'),
page(5,N,T,kicker("PASO 2 · SUMA")+big("SALBUTAMOL",168,R,True)+'<div style="font-size:62px;font-weight:800;line-height:1.2">10–20 mg nebulizado en 10 min</div>'+f'<div style="border-top:4px solid {K};padding-top:28px;font-size:40px;line-height:1.4;color:{G}">Complemento de la insulina: el efecto es aditivo. Puede producir taquicardia. Bicarbonato solo si hay acidosis metabólica.</div>'),
page(6,N,T,kicker("PASO 3 · ELIMINA")+big("SACA EL POTASIO",128,nowrap=True)+f'<div style="display:flex;flex-direction:column;gap:22px">{line("Diuréticos de asa, si la función renal lo permite")}{line("Captores digestivos: patiromer o ciclosilicato")}{line("Hemodiálisis: de elección en la emergencia, sobre todo en pacientes en diálisis",True)}</div>'+f'<div style="font-size:36px;line-height:1.4;color:{G}">Solo desplazar y eliminar reducen la potasemia.</div>'),
page(7,N,T,ficha_body("HIPERPOTASEMIA","Adulto",[("GRAVE","K ≥ 6,5 mEq/L o repercusión en el ECG"),("1. PROTEGE","Gluconato cálcico 1.000 mg (10 ml al 10 %) IV en 2–3 min. Repetible cada 30–60 min",True),("2. DESPLAZA","Insulina rápida 10 UI en 500 ml de glucosado al 10 % en 1 h"),("Y SUMA","Salbutamol nebulizado 10–20 mg en 10 min"),("SI ACIDOSIS","Bicarbonato sódico"),("3. ELIMINA","Diurético de asa, captores digestivos, hemodiálisis")],"Ortiz A, et al. Nefrología 2023;43(5):765-82 (consenso SEN, SEMES, SEEN, SEMI y SEC)",size=112),ficha="02"),
]
out = sys.argv[1] if len(sys.argv)>1 else "out"
render(P,out,"hiperpotasemia")
